// C++14 and later allows more expressive constexpr functions
class Point {
public:
  constexpr Point(double xVal, double yVal) noexcept : x(xVal), y(yVal) {}

  constexpr double xValue() const noexcept { return x; }
  constexpr double yValue() const noexcept { return y; }

  // C++14 allows constexpr setters that mutate state
  constexpr void setX(double newX) noexcept { x = newX; }
  constexpr void setY(double newY) noexcept { y = newY; }

private:
  double x, y;
};

// Function to create and modify a Point at compile time (C++14)
constexpr Point makeAndModifyPoint() {
  Point p(1.0, 1.0); // Create local object
  p.setX(5.0);       // Mutate it
  p.setY(10.0);      // Mutate it again
  return p;          // Return the modified object
}

// p's value is (5.0, 10.0), computed entirely at compile time
constexpr Point p = makeAndModifyPoint();
